// Simular Worker con Promise para el sandbox
// (Worker real requiere archivo separado y browser)

function crearWorkerSimulado(fn) {
  return {
    postMessage(datos) {
      // Simula ejecución asíncrona en 'otro hilo'
      setTimeout(() => {
        const resultado = fn(datos);
        this._onmessage?.({ data: resultado });
      }, 0);
    },
    set onmessage(fn) {
      this._onmessage = fn;
    },
    terminate() {
      this._onmessage = null;
    },
  };
}

// 'Worker' que ordena arrays
const sortWorker = crearWorkerSimulado(({ array, orden }) => {
  const comparador = orden === 'asc' ? (a, b) => a - b : (a, b) => b - a;
  return { sorted: [...array].sort(comparador) };
});

sortWorker.onmessage = ({ data }) => {
  console.log('Array ordenado:', data.sorted);
};

sortWorker.postMessage({ array: [5, 2, 8, 1, 9, 3], orden: 'asc' });
console.log('Continúa mientras el worker trabaja...');

// Patrón: Worker como pool con Promise
function crearWorkerPool(fn, size = 2) {
  const queue = [];
  const workers = Array.from({ length: size }, () => ({
    ocupado: false,
    fn,
  }));

  function procesarCola() {
    const worker = workers.find(w => !w.ocupado);
    if (!worker || queue.length === 0) return;

    const { datos, resolve } = queue.shift();
    worker.ocupado = true;

    // Simula trabajo asíncrono
    setTimeout(() => {
      const resultado = worker.fn(datos);
      resolve(resultado);
      worker.ocupado = false;
      procesarCola(); // Procesa siguiente tarea
    }, 10);
  }

  return {
    ejecutar(datos) {
      return new Promise(resolve => {
        queue.push({ datos, resolve });
        procesarCola();
      });
    },
  };
}

const pool = crearWorkerPool(n => n * n); // Cuadrado de números

const resultados = await Promise.all(
  [1, 2, 3, 4, 5].map(n => pool.ejecutar(n))
);
console.log('Cuadrados:', resultados); // [1, 4, 9, 16, 25]

