function crearWorkerSimulado(procesarFn) {
  let _handler = null;

  return {
    postMessage(dato) {
      setTimeout(() => {
        const resultado = procesarFn(dato);
        _handler?.({ data: resultado });
      }, 0);
    },
    set onmessage(fn) {
      _handler = fn;
    },
    get onmessage() {
      return _handler;
    },
  };
}

const respuestas = [];
const worker = crearWorkerSimulado(n => n * 3);

worker.onmessage = ({ data }) => respuestas.push(data);

worker.postMessage(5);
worker.postMessage(10);
worker.postMessage(7);

// Esperar a que todos los setTimeout se procesen
await new Promise(r => setTimeout(r, 50));

const total = respuestas.length;
const suma = respuestas.reduce((a, b) => a + b, 0); // 15+30+21=66

console.log('Respuestas:', respuestas);
console.log('Total:', total, '| Suma:', suma);

function procesarEnChunks(array, fn, chunkSize, onProgress) {
  return new Promise(resolve => {
    const resultados = [];
    let indice = 0;

    function procesarChunk() {
      const fin = Math.min(indice + chunkSize, array.length);

      while (indice < fin) {
        resultados.push(fn(array[indice]));
        indice++;
      }

      onProgress?.(indice, array.length);

      if (indice < array.length) {
        setTimeout(procesarChunk, 0); // Cede el hilo
      } else {
        resolve(resultados); // Terminó
      }
    }

    procesarChunk();
  });
}

const progreso = [];
const datos = Array.from({ length: 10 }, (_, i) => i + 1);

const resultados = await procesarEnChunks(
  datos,
  x => x * x,
  3,
  (completados, total) => progreso.push({ completados, total })
);

console.log('Resultados:', resultados);
console.log('Progreso:', progreso);

function crearWorkerPool(fn, { workers: numWorkers = 2 } = {}) {
  let activos = 0;
  const cola = []; // [{ datos, prioridad, resolve }]

  function ejecutarTarea() {
    if (activos >= numWorkers || cola.length === 0) return;

    const tarea = cola.shift();
    activos++;

    setTimeout(() => {
      const resultado = fn(tarea.datos);
      tarea.resolve(resultado);
      activos--;
      ejecutarTarea(); // Ejecuta siguiente si hay
    }, 0);
  }

  return {
    ejecutar(datos, prioridad = 'normal') {
      return new Promise(resolve => {
        const tarea = { datos, prioridad, resolve };
        if (prioridad === 'alta') {
          cola.unshift(tarea); // Al frente
        } else {
          cola.push(tarea); // Al final
        }
        ejecutarTarea();
      });
    },
    pendientes() {
      return cola.length;
    },
  };
}

const orden = [];
const pool = crearWorkerPool(n => {
  orden.push(n);
  return n * 2;
}, { workers: 1 }); // 1 worker para forzar cola

// Encolar varias tareas:
const p1 = pool.ejecutar('normal-1');
const p2 = pool.ejecutar('normal-2');
const p3 = pool.ejecutar('alta-1', 'alta');  // Va al frente
const p4 = pool.ejecutar('alta-2', 'alta');  // Va al frente

const resultados = await Promise.all([p1, p2, p3, p4]);

console.log('Orden de ejecución:', orden);
console.log('Resultados:', resultados);
